package org.apache.lucene.rucene.codec;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Reports the iteration order of the {@code java.util} collections Lucene 10.5.0 serialises, so the
 * Rust port can be compared against a running JVM rather than against its own arithmetic.
 *
 * <p>{@code DataOutput.writeMapOfStrings} and {@code writeSetOfStrings} walk their argument in
 * iteration order (`DataOutput.java:304-310` and `:321-326`), so that order is part of every {@code
 * .fnm}, {@code .si} and {@code segments_N} Lucene writes. For {@link HashMap} and {@link HashSet}
 * the order is a pure function of the keys and of the map's construction history — the spreading
 * function, the table length, the bucket chains and the resize policy — and this fixture is the
 * oracle for all of it.
 *
 * <p>The cases are generated by the Rust side and handed over in a file, so both sides work from
 * byte-identical input and no random number generator has to agree across the two languages.
 *
 * <h2>Protocol</h2>
 *
 * <p>Arguments: {@code <inputFile> <outputFile>}. Each input line is tab-separated:
 *
 * <pre>
 *   shape &lt;TAB&gt; arg &lt;TAB&gt; key1 &lt;TAB&gt; key2 &lt;TAB&gt; ...
 * </pre>
 *
 * <p>Each output line is the collection's size followed by the collection walked in iteration
 * order, tab-separated, in the same order as the input lines. The leading count is what keeps a
 * collection holding only the empty string distinguishable from an empty collection.
 *
 * <h2>Shapes</h2>
 *
 * <ul>
 *   <li>{@code map_put} — {@code new HashMap<>()} then one {@code put} per key. The shape every
 *       literal map in Lucene and in the fixtures has.
 *   <li>{@code map_copy} — {@code map_put}, then {@code new HashMap<>(m)}. The copy constructor
 *       pre-sizes its table from the source size, so it lands on a different table length and
 *       therefore a different order.
 *   <li>{@code map_copy_put} — the {@code FieldInfo.putAttribute} chain: starting from an empty
 *       map, each key is added by {@code new HashMap<>(previous)} followed by one {@code put}
 *       (`FieldInfo.java:674-678`). This is how every codec attribute map in a real segment is
 *       built.
 *   <li>{@code map_capacity} — {@code new HashMap<>(arg)} then one {@code put} per key.
 *   <li>{@code map_put_all} — {@code new HashMap<>()}, the first {@code arg} keys put one by one,
 *       then {@code putAll} of the rest.
 *   <li>{@code map_remove_reinsert} — every key put, then the first {@code arg} removed and put
 *       again, which moves them to the tail of their bucket.
 *   <li>{@code set_add} — {@code new HashSet<>()} then one {@code add} per key. The shape {@code
 *       SegmentInfo.setFiles} builds (`SegmentInfo.java:309-320`).
 *   <li>{@code set_copy} — {@code new HashSet<>(collection)}, whose backing map is pre-sized by an
 *       expression that has changed between JDK releases and is therefore measured here rather
 *       than assumed.
 * </ul>
 */
public final class JavaCollectionsFixture {

  private JavaCollectionsFixture() {}

  public static void main(String[] args) throws IOException {
    if (args.length != 2) {
      throw new IllegalArgumentException("usage: JavaCollectionsFixture <inputFile> <outputFile>");
    }
    List<String> lines = Files.readAllLines(Path.of(args[0]), StandardCharsets.UTF_8);
    StringBuilder out = new StringBuilder();
    for (String line : lines) {
      if (line.isEmpty()) {
        continue;
      }
      List<String> ordered = run(line);
      // The count leads the line so that a one-element collection holding the
      // empty string is not indistinguishable from an empty collection.
      out.append(ordered.size());
      for (String key : ordered) {
        out.append('\t').append(key);
      }
      out.append('\n');
    }
    Files.writeString(Path.of(args[1]), out.toString(), StandardCharsets.UTF_8);
  }

  /** Runs one case and returns its collection in iteration order. */
  private static List<String> run(String line) {
    String[] parts = line.split("\t", -1);
    String shape = parts[0];
    int arg = Integer.parseInt(parts[1]);
    List<String> keys = new ArrayList<>();
    for (int i = 2; i < parts.length; i++) {
      keys.add(unescape(parts[i]));
    }

    return switch (shape) {
      case "map_put" -> order(mapPut(keys));
      case "map_copy" -> order(new HashMap<>(mapPut(keys)));
      case "map_copy_put" -> order(mapCopyPut(keys));
      case "map_capacity" -> order(mapCapacity(arg, keys));
      case "map_put_all" -> order(mapPutAll(arg, keys));
      case "map_remove_reinsert" -> order(mapRemoveReinsert(arg, keys));
      case "map_compute_if_absent" -> order(mapComputeIfAbsent(keys));
      case "map_compute_remove" -> order(mapComputeRemove(arg, keys));
      case "set_add" -> setOrder(setAdd(keys));
      case "set_copy" -> setOrder(new HashSet<>(setAdd(keys)));
      default -> throw new IllegalArgumentException("unknown shape: " + shape);
    };
  }

  private static Map<String, String> mapPut(List<String> keys) {
    Map<String, String> map = new HashMap<>();
    for (String key : keys) {
      map.put(key, "v");
    }
    return map;
  }

  /** Exactly how {@code ReadersAndUpdates.addDVUpdate} fills {@code pendingDVUpdates}. */
  private static Map<String, String> mapComputeIfAbsent(List<String> keys) {
    Map<String, String> map = new HashMap<>();
    for (String key : keys) {
      map.computeIfAbsent(key, k -> "v");
    }
    return map;
  }

  /**
   * {@code pendingDVUpdates} after a write prunes the first {@code count} fields through the
   * entry-set iterator and later updates add them back.
   */
  private static Map<String, String> mapComputeRemove(int count, List<String> keys) {
    Map<String, String> map = mapComputeIfAbsent(keys);
    Set<String> pruned = new HashSet<>(keys.subList(0, Math.min(count, keys.size())));
    map.entrySet().removeIf(entry -> pruned.contains(entry.getKey()));
    for (int i = 0; i < Math.min(count, keys.size()); i++) {
      map.computeIfAbsent(keys.get(i), k -> "v");
    }
    return map;
  }

  private static Map<String, String> mapCopyPut(List<String> keys) {
    Map<String, String> map = new HashMap<>();
    for (String key : keys) {
      // Exactly `FieldInfo.putAttribute`: copy, then put into the copy.
      Map<String, String> next = new HashMap<>(map);
      next.put(key, "v");
      map = next;
    }
    return map;
  }

  private static Map<String, String> mapCapacity(int capacity, List<String> keys) {
    Map<String, String> map = new HashMap<>(capacity);
    for (String key : keys) {
      map.put(key, "v");
    }
    return map;
  }

  private static Map<String, String> mapPutAll(int direct, List<String> keys) {
    Map<String, String> map = new HashMap<>();
    Map<String, String> rest = new HashMap<>();
    for (int i = 0; i < keys.size(); i++) {
      if (i < direct) {
        map.put(keys.get(i), "v");
      } else {
        rest.put(keys.get(i), "v");
      }
    }
    map.putAll(rest);
    return map;
  }

  private static Map<String, String> mapRemoveReinsert(int count, List<String> keys) {
    Map<String, String> map = mapPut(keys);
    for (int i = 0; i < count && i < keys.size(); i++) {
      map.remove(keys.get(i));
      map.put(keys.get(i), "v");
    }
    return map;
  }

  private static Set<String> setAdd(List<String> keys) {
    Set<String> set = new HashSet<>();
    set.addAll(keys);
    return set;
  }

  private static List<String> order(Map<String, String> map) {
    List<String> keys = new ArrayList<>(map.size());
    for (Map.Entry<String, String> entry : map.entrySet()) {
      keys.add(escape(entry.getKey()));
    }
    return keys;
  }

  private static List<String> setOrder(Set<String> set) {
    List<String> keys = new ArrayList<>(set.size());
    for (String value : set) {
      keys.add(escape(value));
    }
    return keys;
  }

  /** Keeps tabs, newlines and backslashes out of the tab-separated wire format. */
  private static String escape(String s) {
    return s.replace("\\", "\\\\").replace("\t", "\\t").replace("\n", "\\n").replace("\r", "\\r");
  }

  private static String unescape(String s) {
    StringBuilder sb = new StringBuilder(s.length());
    for (int i = 0; i < s.length(); i++) {
      char c = s.charAt(i);
      if (c == '\\' && i + 1 < s.length()) {
        char next = s.charAt(++i);
        switch (next) {
          case 't' -> sb.append('\t');
          case 'n' -> sb.append('\n');
          case 'r' -> sb.append('\r');
          case '\\' -> sb.append('\\');
          default -> sb.append('\\').append(next);
        }
      } else {
        sb.append(c);
      }
    }
    return sb.toString();
  }
}
